// This file is generated by AI.

// 护栏: 核对 styles.css 与组件模板的类名是否一致, 不一致即退出 1。
// 用法: node scripts/check-css-classes.mjs
//
// 查这几件事: 花括号配对; 选择器列表里不允许出现注释 (规则体被删空后留下的悬空列表);
// 模板类名必须有规则 (UNSTYLED_OK 为豁免); 组件不得带 <style> 块; 结构性类名必须真的被用到。
// 另外报告一遍无人引用的类名 —— **只报告**, 它同时包含运行期拼出的名字与尚未重建界面的旧规则。

import { readFileSync } from 'node:fs';
import { join, relative } from 'node:path';

import { editorRoot, walkFiles } from './walk.mjs';

const srcDir = join(editorRoot, 'src');
const cssPath = join(srcDir, 'styles.css');
const css = readFileSync(cssPath, 'utf8');

/** 每个文件只读一次 (下面两轮扫描都要看源码)。 */
const texts = new Map();
const read = (file) => {
  let text = texts.get(file);
  if (text === undefined) {
    text = readFileSync(file, 'utf8');
    texts.set(file, text);
  }
  return text;
};

/**
 * 允许"用到但没有规则"的类名。加进来必须有理由:
 * * `icon` —— Icon.svelte 的标记类, 尺寸由上下文决定;
 * * `status-cursor` —— 同样只有标记作用, 没有专属规则。
 */
const UNSTYLED_OK = new Set(['icon', 'status-cursor']);

/**
 * 由**代码**而不是模板拼出来的类名 (Monaco 装饰、view zone、body 状态类): 模板扫描看不到,
 * 因此显式列出来核对它们是否还在样式表里。
 */
const PROGRAMMATIC = [
  'cgmr',
  'editor-block-glyph',
  'diff-gutter-added',
  'diff-gutter-modified',
  'diff-gutter-deleted',
  'inline-diff-zone',
  'inline-diff-zone-add',
  'inline-diff-zone-del',
  'inline-diff-sign',
  'live-preview-glyph-executing',
  'live-preview-glyph-done',
  'live-preview-glyph-passed',
  'live-preview-glyph-failed',
  'live-preview-line-executing',
  'live-preview-line-done',
  'live-preview-line-passed',
  'live-preview-line-failed',
  'preprocess-block-glyph',
  'preprocess-block-line',
  'resizing',
];

/**
 * 结构性类名: 它们**必须**在某个组件里被用到 (这一条管反方向 —— "规则还在, 但没有任何元素带它")。
 * 漏掉一层承载布局的 `<div class="file-tree">` 包裹会让布局塌掉, 而构建与测试全绿。
 * 维护方式: 新增一层承载布局的容器类时, 顺手加到这里。
 */
const REQUIRED_STRUCTURAL = [
  'file-tree',
  'file-badges',
  'git-file-status',
  'sidebar-content',
  'sidebar-tabs',
  'sidebar-preview',
  'sidebar-resizer',
  'editor-area',
  'editor-workspace',
  'tab-strip',
  'tab-strip-item',
  'status-bar',
  'diag-dock',
  'scene-voice-panel',
  'project-tab',
  'repository',
  'code-editor-host',
  'modal-surface',
  'dialog-surface',
  'git-commit-row',
  'voice-line-highlight',
];

const problems = [];
const note = (message) => problems.push(message);

// ---------------------------------------------------------------- 1. 花括号配对
const opens = (css.match(/\{/g) || []).length;
const closes = (css.match(/\}/g) || []).length;
if (opens !== closes) note(`styles.css 花括号不配对: { ×${opens}, } ×${closes}`);

// ---------------------------------------------------------------- 2. 选择器列表里的注释
{
  const lines = css.split('\n');
  let inRuleBody = false;
  let pendingSelector = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    if (inRuleBody) {
      if (trimmed.startsWith('}')) inRuleBody = false;
      continue;
    }
    if (trimmed.startsWith('/*')) {
      if (pendingSelector) {
        note(
          `styles.css:${i + 1} 选择器列表里出现注释 (规则体疑似被删掉、列表悬空): ` +
            `上一条选择器行是 "${lines[i - 1]?.trim()}"`
        );
      }
      // 跳过整个注释
      while (i < lines.length && !lines[i].includes('*/')) i++;
      continue;
    }
    if (trimmed === '') continue;
    if (trimmed.endsWith(',')) {
      pendingSelector = true;
      continue;
    }
    if (trimmed.includes('{')) {
      pendingSelector = false;
      inRuleBody = !trimmed.includes('}');
      continue;
    }
    pendingSelector = false;
  }
}

// ---------------------------------------------------------------- 3/4. 组件
const sourceFiles = walkFiles(srcDir);
const used = new Map();
const styleBlocks = [];
for (const file of sourceFiles) {
  const rel = relative(srcDir, file).replace(/\\/g, '/');
  if (!file.endsWith('.svelte')) continue;
  const text = read(file);
  // 头部文档注释里会写到 "<style>" 这个词, 先去掉注释再判断真实存在的样式块
  if (/<style[\s>]/.test(text.replace(/<!--[\s\S]*?-->/g, ''))) styleBlocks.push(rel);

  const collect = (token, where) => {
    if (!/^-?[A-Za-z_][A-Za-z0-9_-]*$/.test(token)) return;
    const target = used.get(token) ?? new Set();
    target.add(where);
    used.set(token, target);
  };
  for (const m of text.matchAll(/\bclass="([^"]*)"/g)) {
    for (const token of m[1].split(/\s+/)) collect(token, rel);
  }
  for (const m of text.matchAll(/\bclass:([A-Za-z0-9_-]+)/g)) collect(m[1], rel);
  for (const m of text.matchAll(/\bclass=\{[^}]*\}/g)) {
    for (const s of m[0].matchAll(/'([^']+)'/g)) for (const token of s[1].split(/\s+/)) collect(token, rel);
  }
}

for (const rel of styleBlocks) {
  note(`${rel} 带 <style> 块 —— 组件样式必须写进 src/styles.css (否则作用域规则会与全局规则分叉)`);
}

/** 样式表里定义过的类名 */
const styled = new Set([...css.matchAll(/\.(-?[A-Za-z_][A-Za-z0-9_-]*)/g)].map((m) => m[1]));

for (const [token, where] of [...used].sort()) {
  if (styled.has(token) || UNSTYLED_OK.has(token)) continue;
  note(`模板用到但 styles.css 里没有规则的类名: .${token}  (${[...where].join(', ')})`);
}

for (const token of PROGRAMMATIC) {
  if (!styled.has(token)) note(`代码拼出的类名在 styles.css 里没有规则: .${token}`);
}

// 结构性类名必须在某个组件里出现 (模板、`class:` 指令、或代码里的字符串都算)
{
  const sources = sourceFiles
    .filter((file) => /\.(svelte|ts)$/.test(file))
    .map(read)
    .join('\n');
  for (const token of REQUIRED_STRUCTURAL) {
    const present = new RegExp(`[^A-Za-z0-9_-]${token}[^A-Za-z0-9_-]`).test(sources);
    if (!present) {
      note(
        `结构性类名在模板与代码里都没有出现: .${token} —— 规则还在, 但没有任何元素带它, ` +
          `这类"漏掉一层包裹元素"的改动不会报错, 只会让布局塌掉`
      );
    }
  }
}

if (problems.length > 0) {
  console.log(`发现 ${problems.length} 个问题:`);
  for (const problem of problems) console.log(`  - ${problem}`);
  process.exitCode = 1;
} else {
  console.log(`样式表与模板一致: ${used.size} 个模板类名全部有规则, ${PROGRAMMATIC.length} 个拼出的类名也在。`);
}

const unused = [...styled].filter((name) => !used.has(name) && !PROGRAMMATIC.includes(name));
console.log(
  `(报告) styles.css 定义了 ${styled.size} 个类名, 其中 ${unused.length} 个没在模板里出现 —— ` +
    `**不要据此自动删除**: 里面既有运行期拼出来的名字, 也有尚未重建的界面用的旧规则。`
);
